// order.service.ts
// Node.js Order Service — framework-agnostic (own DB repository + Kafka producer client)

interface OrderItem {
  productId: string;
  quantity: number;
}

interface CreateOrderDto {
  customerId: string;
  items: OrderItem[];
}

interface Order {
  id: string;
  customerId: string;
  items: OrderItem[];
  status: 'CREATED';
  createdAt: Date;
}

interface OrderCreatedEvent {
  orderId: string;
  items: OrderItem[];
  quantities: number[];
}

interface OrderRepository {
  save(order: Order): Promise<void>;
}

interface KafkaMessage {
  value: string;
}

interface KafkaProducer {
  send(args: { topic: string; messages: KafkaMessage[] }): Promise<void>;
}

function generateOrderId(): string {
  return `ord_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

export class OrderService {
  constructor(
    private readonly orderRepository: OrderRepository,
    private readonly kafkaProducer: KafkaProducer,
  ) {}

  async createOrder(dto: CreateOrderDto): Promise<Order> {
    // STEP 1 — DB write, committed on its own.
    // This "transaction" covers ONLY the order row. Once save() resolves,
    // the order is durably committed to the Orders DB.
    const order: Order = {
      id: generateOrderId(),
      customerId: dto.customerId,
      items: dto.items,
      status: 'CREATED',
      createdAt: new Date(),
    };

    await this.orderRepository.save(order);

    // STEP 2 — broker publish, a SEPARATE call AFTER the commit above.
    // This is an independent network call to a different system (Kafka);
    // it is NOT inside the DB transaction that just committed.
    const event: OrderCreatedEvent = {
      orderId: order.id,
      items: order.items,
      quantities: order.items.map((item) => item.quantity),
    };

    try {
      await this.kafkaProducer.send({
        topic: 'order.created',
        messages: [{ value: JSON.stringify(event) }],
      });
    } catch (err) {
      // "Fix" that was shipped after the first few missing events were noticed:
      // retry once, then just log. This does NOT close the gap — if the pod
      // is killed, the process crashes, or an exception is thrown anywhere
      // between the save() above and this retry, the order stays committed
      // in the Orders DB but the order.created event is never emitted. The
      // Inventory consumer (which decrements stock for each order.created
      // message it receives) never fires, and the two databases diverge
      // permanently for that order.
      console.error('kafkaProducer.send failed, retrying once', err);
      try {
        await this.kafkaProducer.send({
          topic: 'order.created',
          messages: [{ value: JSON.stringify(event) }],
        });
      } catch (retryErr) {
        console.error('retry also failed, order.created event lost', retryErr);
      }
    }

    return order;
  }
}
